from semver import VersionInfo
for version in (VersionInfo(1, 2, 3, 'rc.1', 'build.5'), VersionInfo(1)):
    parts = (version.major, version.minor, version.patch, version.prerelease, version.build)
    assert version.to_tuple() == parts
    result = version.to_dict()
    assert isinstance(result, dict)
    assert result == dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), parts))
    result['major'] = 99
    assert version.major == 1
    for i in range(-5, 5):
        assert version[i] == parts[i]
    for s in (slice(None), slice(1, 4), slice(None, None, -1), slice(-4, -1), slice(None, None, 2), slice(10, 20)):
        assert version[s] == parts[s]
    for i in (-6, 5):
        try:
            version[i]
        except IndexError:
            pass
        else:
            raise AssertionError('expected IndexError')
    for i in ('major', 1.5, None):
        try:
            version[i]
        except TypeError:
            pass
        else:
            raise AssertionError('expected TypeError')
print('Accessor and indexing checks passed')
PY
